<?php
declare(strict_types=1);
require_once __DIR__.'/config.php';require_once __DIR__.'/TokenService.php';require_once __DIR__.'/NotificationService.php';
function medcon_send_verification(PDO $pdo,int $userId):bool{try{$rate=$pdo->prepare('SELECT COUNT(*) FROM email_verification_tokens WHERE user_id=? AND created_at>DATE_SUB(NOW(),INTERVAL 15 MINUTE)');$rate->execute([$userId]);if((int)$rate->fetchColumn()>=3)return false;$verification=(new MedconTokenService($pdo))->createVerification($userId);$config=medcon_mail_config();return medcon_notify($pdo,'account.created',$userId,'account.created:user:'.$userId.':verification:'.$verification['id'],['action_url'=>$config['base_url'].'/app/verify-email.php?token='.rawurlencode($verification['token'])],'user',$userId);}catch(Throwable $e){error_log('Medcon verification request failed.');return false;}}
function medcon_notify_affiliate(PDO $pdo,int $agentId,int $studentId):bool{$q=$pdo->prepare('SELECT a.user_id,u.first_name,u.last_name FROM agents a JOIN students s ON s.id=? JOIN users u ON u.id=s.user_id WHERE a.id=? LIMIT 1');$q->execute([$studentId,$agentId]);$row=$q->fetch();if(!$row)return false;$config=medcon_mail_config();return medcon_notify($pdo,'affiliate.new_student',(int)$row['user_id'],'affiliate.new_student:agent:'.$agentId.':student:'.$studentId,['student_name'=>$row['first_name'].' '.$row['last_name'],'action_url'=>$config['base_url'].'/app/agent/dashboard.php'],'student',$studentId);}
